//! Event maps in EvtxECmd's format (Eric Zimmerman, MIT): per
//! `EventId` + `Channel` + `Provider`, XPath expressions pull values out of
//! the event XML and fill the standard columns `UserName`, `RemoteHost`,
//! `ExecutableInfo` and `PayloadData1…6`, with optional regex `Refine`
//! and value `Lookups`. Semantics follow `EvtxECmd/evtx/EventRecord.cs`.
//!
//! The 468 maps shipped with EvtxECmd are embedded (`maps/evtxecmd.yaml`,
//! regenerated by `scripts/update-evtx-maps.sh`); postmortem adds maps for
//! legacy `.evt` logs (`maps/legacy.yaml`), where a value `#N` means the
//! N-th insertion string. Examiners can load more maps from a directory.

use std::collections::HashMap;
use std::path::Path;
use std::sync::OnceLock;

use roxmltree::{Document, Node};
use yaml_rust2::{Yaml, YamlLoader};

use crate::evtx_log::string_value;
use crate::{EventRecord, LogFormat};

const EVTXECMD_MAPS: &str = include_str!("../maps/evtxecmd.yaml");
const LEGACY_MAPS: &str = include_str!("../maps/legacy.yaml");

/// The standard output columns of a mapped event.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct Mapped {
    pub description: String,
    pub user_name: Option<String>,
    pub remote_host: Option<String>,
    pub executable_info: Option<String>,
    pub payload: [Option<String>; 6],
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Property {
    UserName,
    RemoteHost,
    ExecutableInfo,
    Payload(usize),
}

impl Property {
    fn parse(s: &str) -> Option<Self> {
        let u = s.trim().to_ascii_uppercase();
        Some(match u.as_str() {
            "USERNAME" => Self::UserName,
            "REMOTEHOST" => Self::RemoteHost,
            "EXECUTABLEINFO" => Self::ExecutableInfo,
            _ => Self::Payload(
                u.strip_prefix("PAYLOADDATA")?
                    .parse::<usize>()
                    .ok()
                    .filter(|n| (1..=6).contains(n))?
                    - 1,
            ),
        })
    }
}

/// One step of the supported XPath subset.
#[derive(Debug, Clone, PartialEq, Eq)]
struct Step {
    name: String,
    pred: Option<Pred>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum Pred {
    AttrEq(String, String),
    Index(usize),
}

/// `/a/b[@Name="x"]/c[2]/@attr` or `#N` (EVT insertion string).
#[derive(Debug, Clone, PartialEq, Eq)]
enum XPath {
    Path {
        steps: Vec<Step>,
        attr: Option<String>,
    },
    Insertion(usize),
}

impl XPath {
    fn parse(s: &str) -> Option<Self> {
        let s = s.trim();
        if let Some(n) = s.strip_prefix('#') {
            return n.parse().ok().map(Self::Insertion);
        }
        let mut steps = Vec::new();
        let mut attr = None;
        for part in s.strip_prefix('/')?.split('/') {
            if let Some(a) = part.strip_prefix('@') {
                attr = Some(a.to_owned());
                continue;
            }
            let (name, pred) = match part.split_once('[') {
                Some((name, rest)) => {
                    let inner = rest.strip_suffix(']')?;
                    let pred = if let Some(p) = inner.strip_prefix('@') {
                        let (k, v) = p.split_once('=')?;
                        Pred::AttrEq(
                            k.trim().to_owned(),
                            v.trim().trim_matches(['"', '\'']).to_owned(),
                        )
                    } else {
                        Pred::Index(inner.trim().parse().ok()?)
                    };
                    (name, Some(pred))
                }
                None => (part, None),
            };
            steps.push(Step {
                name: name.to_owned(),
                pred,
            });
        }
        Some(Self::Path { steps, attr })
    }

    fn select(&self, doc: &Document<'_>, rec: &EventRecord) -> Option<String> {
        match self {
            Self::Insertion(n) => rec.nth(*n).map(str::to_owned),
            Self::Path { steps, attr } => {
                let root = doc.root();
                let node = find(root, steps)?;
                match attr {
                    Some(a) => node.attribute(a.as_str()).map(str::to_owned),
                    None => Some(string_value(node)),
                }
            }
        }
    }
}

/// First node (document order) matching `steps` below `n`.
fn find<'a, 'i>(n: Node<'a, 'i>, steps: &[Step]) -> Option<Node<'a, 'i>> {
    let (step, rest) = steps.split_first()?;
    let mut index = 0;
    for c in n.children().filter(Node::is_element) {
        if step.name != "*" && c.tag_name().name() != step.name {
            continue;
        }
        index += 1;
        let ok = match &step.pred {
            None => true,
            Some(Pred::AttrEq(k, v)) => c.attribute(k.as_str()) == Some(v.as_str()),
            Some(Pred::Index(i)) => index == *i,
        };
        if !ok {
            continue;
        }
        if rest.is_empty() {
            return Some(c);
        }
        if let Some(found) = find(c, rest) {
            return Some(found);
        }
    }
    None
}

#[derive(Debug, Clone)]
struct ValueDef {
    name: String,
    xpath: XPath,
    refine: Option<fancy_regex::Regex>,
}

#[derive(Debug, Clone)]
struct Entry {
    property: Property,
    template: String,
    values: Vec<ValueDef>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum LookupKey {
    Text(String),
    Int(i64),
}

#[derive(Debug, Clone)]
struct Lookup {
    name: String,
    default: String,
    values: Vec<(LookupKey, String)>,
}

impl Lookup {
    fn resolve(&self, v: &str) -> String {
        // Exact text first (EvtxECmd), then numeric equality so `0xb`
        // matches a `0x0B` or `11` key.
        if let Some((_, out)) = self
            .values
            .iter()
            .find(|(k, _)| matches!(k, LookupKey::Text(t) if t == v))
        {
            return out.clone();
        }
        let num = parse_int(v);
        for (k, out) in &self.values {
            let hit = match k {
                LookupKey::Text(t) => {
                    t.eq_ignore_ascii_case(v) || (num.is_some() && parse_int(t) == num)
                }
                LookupKey::Int(i) => num == Some(*i),
            };
            if hit {
                return out.clone();
            }
        }
        format!("{} ({v})", self.default)
    }
}

fn parse_int(s: &str) -> Option<i64> {
    let s = s.trim();
    match s.strip_prefix("0x").or_else(|| s.strip_prefix("0X")) {
        Some(h) => i64::from_str_radix(h, 16).ok(),
        None => s.parse().ok(),
    }
}

/// One event map.
#[derive(Debug, Clone)]
pub struct EventMap {
    pub description: String,
    pub event_id: u32,
    pub channel: String,
    pub provider: String,
    entries: Vec<Entry>,
    lookups: Vec<Lookup>,
}

fn ystr(y: &Yaml) -> Option<String> {
    match y {
        Yaml::String(s) | Yaml::Real(s) => Some(s.clone()),
        Yaml::Integer(i) => Some(i.to_string()),
        Yaml::Boolean(b) => Some(b.to_string()),
        _ => None,
    }
}

impl EventMap {
    fn from_yaml(doc: &Yaml) -> Result<Self, String> {
        let event_id = match &doc["EventId"] {
            Yaml::Integer(i) => u32::try_from(*i).map_err(|_| "bad EventId".to_owned())?,
            other => ystr(other)
                .and_then(|s| s.trim().parse().ok())
                .ok_or("missing EventId")?,
        };
        let text = |k: &str| ystr(&doc[k]).unwrap_or_default();
        let mut entries = Vec::new();
        for m in doc["Maps"].as_vec().map(Vec::as_slice).unwrap_or_default() {
            let Some(property) = ystr(&m["Property"]).as_deref().and_then(Property::parse) else {
                continue;
            };
            let mut values = Vec::new();
            for v in m["Values"].as_vec().map(Vec::as_slice).unwrap_or_default() {
                let (Some(name), Some(xp)) = (
                    ystr(&v["Name"]),
                    ystr(&v["Value"]).as_deref().and_then(XPath::parse),
                ) else {
                    continue;
                };
                let refine = ystr(&v["Refine"])
                    .filter(|r| !r.is_empty())
                    .and_then(|r| fancy_regex::Regex::new(&format!("(?i){r}")).ok());
                values.push(ValueDef {
                    name,
                    xpath: xp,
                    refine,
                });
            }
            entries.push(Entry {
                property,
                template: ystr(&m["PropertyValue"]).unwrap_or_default(),
                values,
            });
        }
        let mut lookups = Vec::new();
        for l in doc["Lookups"]
            .as_vec()
            .map(Vec::as_slice)
            .unwrap_or_default()
        {
            let mut values = Vec::new();
            if let Some(h) = l["Values"].as_hash() {
                for (k, v) in h {
                    let key = match k {
                        Yaml::Integer(i) => LookupKey::Int(*i),
                        other => LookupKey::Text(ystr(other).unwrap_or_default()),
                    };
                    values.push((key, ystr(v).unwrap_or_default()));
                }
            }
            lookups.push(Lookup {
                name: ystr(&l["Name"]).unwrap_or_default(),
                default: ystr(&l["Default"]).unwrap_or_default(),
                values,
            });
        }
        Ok(Self {
            description: text("Description"),
            event_id,
            channel: text("Channel"),
            provider: text("Provider"),
            entries,
            lookups,
        })
    }

    /// Applies the map to a record (EvtxECmd `BuildProperties`).
    pub fn apply(&self, rec: &EventRecord) -> Mapped {
        let mut out = Mapped {
            description: self.description.clone(),
            ..Mapped::default()
        };
        let xml = rec.xml.as_deref().unwrap_or("<Event/>");
        let Ok(doc) = Document::parse(xml) else {
            return out;
        };
        for e in &self.entries {
            if e.values.is_empty() {
                continue;
            }
            let mut value = e.template.clone();
            for v in &e.values {
                let mut got = v.xpath.select(&doc, rec).unwrap_or_default();
                if let Some(re) = &v.refine {
                    let hits: Vec<String> = re
                        .find_iter(&got)
                        .filter_map(Result::ok)
                        .map(|m| m.as_str().to_owned())
                        .collect();
                    if !hits.is_empty() {
                        got = hits.join(" | ");
                    }
                }
                if let Some(l) = self
                    .lookups
                    .iter()
                    .find(|l| l.name.eq_ignore_ascii_case(&v.name))
                {
                    got = l.resolve(&got);
                }
                value = value.replace(&format!("%{}%", v.name), &got);
            }
            let slot = match e.property {
                Property::UserName => &mut out.user_name,
                Property::RemoteHost => &mut out.remote_host,
                Property::ExecutableInfo => &mut out.executable_info,
                Property::Payload(i) => match out.payload.get_mut(i) {
                    Some(s) => s,
                    None => continue,
                },
            };
            *slot = Some(value);
        }
        out
    }
}

/// Loads every document of `yaml` into `table`; returns problems found.
fn load_into(table: &mut HashMap<(u32, String, String), EventMap>, yaml: &str) -> Vec<String> {
    let mut warnings = Vec::new();
    // Each document is loaded on its own so one bad map cannot hide
    // the others (EvtxECmd loads one file per map).
    for (i, part) in split_documents(yaml).iter().enumerate() {
        let docs = match YamlLoader::load_from_str(&quote_numeric_keys(part)) {
            Ok(d) => d,
            Err(e) => {
                warnings.push(format!("document {}: {e}", i + 1));
                continue;
            }
        };
        for doc in docs.iter().filter(|d| !d.is_null()) {
            match EventMap::from_yaml(doc) {
                Ok(m) => {
                    table.insert(key(m.event_id, &m.channel, &m.provider), m);
                }
                Err(e) => warnings.push(format!("document {}: {e}", i + 1)),
            }
        }
    }
    warnings
}

/// Splits a multi-document YAML stream on `---` lines.
fn split_documents(yaml: &str) -> Vec<String> {
    let mut docs = vec![String::new()];
    for line in yaml.lines() {
        if line.trim_end() == "---" {
            docs.push(String::new());
        } else if let Some(d) = docs.last_mut() {
            d.push_str(line);
            d.push('\n');
        }
    }
    docs.retain(|d| {
        d.lines()
            .any(|l| !l.trim().is_empty() && !l.trim_start().starts_with('#'))
    });
    docs
}

/// Quotes numeric mapping keys (`  0x1A: …`, `  7: …`) so they stay text,
/// as EvtxECmd's YAML library reads lookup tables; otherwise `0x10` and
/// `16` would collide as the same integer key.
fn quote_numeric_keys(doc: &str) -> String {
    let mut out = String::with_capacity(doc.len() + 64);
    for line in doc.lines() {
        let trimmed = line.trim_start();
        let indent = &line[..line.len() - trimmed.len()];
        let quoted = trimmed.split_once(':').filter(|(k, _)| {
            let k = k.trim();
            !k.is_empty()
                && (k.chars().all(|c| c.is_ascii_digit() || c == '-')
                    || k.strip_prefix("0x")
                        .or_else(|| k.strip_prefix("0X"))
                        .is_some_and(|h| !h.is_empty() && h.chars().all(|c| c.is_ascii_hexdigit())))
        });
        match quoted {
            Some((k, rest)) => {
                out.push_str(indent);
                out.push('"');
                out.push_str(k.trim());
                out.push_str("\":");
                out.push_str(rest);
            }
            None => out.push_str(line),
        }
        out.push('\n');
    }
    out
}

/// A set of maps keyed like EvtxECmd (`EventId-CHANNEL-PROVIDER`).
#[derive(Debug, Clone, Default)]
pub struct MapSet {
    /// Maps for EVTX records (XPath values).
    maps: HashMap<(u32, String, String), EventMap>,
    /// Maps for legacy `.evt` records (`#N` values). Kept apart because
    /// some event ids (6005, 7036, …) exist in both eras with different
    /// field layouts.
    legacy: HashMap<(u32, String, String), EventMap>,
}

fn key(id: u32, channel: &str, provider: &str) -> (u32, String, String) {
    (id, channel.to_uppercase(), provider.to_uppercase())
}

impl MapSet {
    /// EvtxECmd's maps plus postmortem's legacy `.evt` maps (parsed once).
    pub fn builtin() -> &'static Self {
        static SET: OnceLock<MapSet> = OnceLock::new();
        SET.get_or_init(|| {
            let mut s = Self::default();
            let mut warnings = s.load_str(EVTXECMD_MAPS);
            warnings.extend(s.load_legacy_str(LEGACY_MAPS));
            for w in warnings {
                tracing::debug!("built-in event map: {w}");
            }
            s
        })
    }

    /// Adds the maps in `yaml` (one or more documents); later maps
    /// replace earlier ones with the same key. Returns problems found.
    pub fn load_str(&mut self, yaml: &str) -> Vec<String> {
        let mut table = std::mem::take(&mut self.maps);
        let w = load_into(&mut table, yaml);
        self.maps = table;
        w
    }

    /// Adds maps for legacy `.evt` logs (values `#N`).
    pub fn load_legacy_str(&mut self, yaml: &str) -> Vec<String> {
        let mut table = std::mem::take(&mut self.legacy);
        let w = load_into(&mut table, yaml);
        self.legacy = table;
        w
    }

    /// Adds every `*.map` file in `dir` (custom maps, as EvtxECmd's `--maps`).
    pub fn load_dir(&mut self, dir: &Path) -> std::io::Result<Vec<String>> {
        let mut warnings = Vec::new();
        for entry in std::fs::read_dir(dir)? {
            let p = entry?.path();
            if p.extension().is_some_and(|e| e.eq_ignore_ascii_case("map")) {
                let text = std::fs::read_to_string(&p)?;
                warnings.extend(
                    self.load_str(text.trim_start_matches('\u{feff}'))
                        .into_iter()
                        .map(|w| format!("{}: {w}", p.display())),
                );
            }
        }
        Ok(warnings)
    }

    /// Number of maps (both formats).
    pub fn len(&self) -> usize {
        self.maps.len() + self.legacy.len()
    }

    pub fn is_empty(&self) -> bool {
        self.len() == 0
    }

    /// The map for a record. Legacy `.evt` records match on event id and
    /// source, with the channel taken from the log they came from.
    pub fn get(&self, rec: &EventRecord) -> Option<&EventMap> {
        let table = match rec.format {
            LogFormat::Evtx => &self.maps,
            LogFormat::Evt => &self.legacy,
        };
        table.get(&key(rec.event_id, &rec.channel, &rec.provider))
    }

    /// Maps a record, if a map exists for it.
    pub fn apply(&self, rec: &EventRecord) -> Option<Mapped> {
        let m = self.get(rec)?;
        if rec.format == LogFormat::Evt || rec.xml.is_some() {
            Some(m.apply(rec))
        } else {
            None
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::evtx_log::{from_xml, tests::LOGON};

    #[test]
    fn builtin_maps_load() {
        let mut s = MapSet::default();
        assert_eq!(s.load_str(EVTXECMD_MAPS), Vec::<String>::new());
        let evtxecmd = s.len();
        assert!(evtxecmd >= 460, "{evtxecmd} EvtxECmd maps");
        assert_eq!(s.load_legacy_str(LEGACY_MAPS), Vec::<String>::new());
        assert_eq!(s.len(), evtxecmd + 43);
        assert_eq!(MapSet::builtin().len(), s.len());
    }

    #[test]
    fn evtxecmd_4624_map_matches_its_documented_output() {
        let rec = from_xml(LOGON.to_owned(), 7, 0).unwrap();
        let m = MapSet::builtin().apply(&rec).unwrap();
        assert_eq!(m.description, "Successful logon");
        assert_eq!(m.user_name.as_deref(), Some("CORP\\WS01$"));
        assert_eq!(m.remote_host.as_deref(), Some("LAPTOP (10.0.0.5)"));
        assert_eq!(m.payload[0].as_deref(), Some("Target: CORP\\alice"));
        assert!(
            m.payload[1].as_deref().unwrap().starts_with("LogonType 10"),
            "{:?}",
            m.payload[1]
        );
        assert_eq!(
            m.executable_info.as_deref(),
            Some("C:\\Windows\\System32\\svchost.exe")
        );
    }

    #[test]
    fn xpath_subset() {
        let xml = r#"<Event xmlns="urn:x"><System><Correlation ActivityID="{A}"/></System>
            <EventData><Data Name="a">1</Data><Data Name="b">2</Data><Data>u1</Data><Data>u2</Data></EventData></Event>"#;
        let doc = Document::parse(xml).unwrap();
        let rec = from_xml(
            "<Event><System><EventID>1</EventID></System></Event>".to_owned(),
            0,
            0,
        )
        .unwrap();
        let sel = |p: &str| XPath::parse(p).unwrap().select(&doc, &rec);
        assert_eq!(
            sel(r#"/Event/EventData/Data[@Name="b"]"#).as_deref(),
            Some("2")
        );
        assert_eq!(sel("/Event/EventData/Data[4]").as_deref(), Some("u2"));
        assert_eq!(
            sel("/Event/System/Correlation/@ActivityID").as_deref(),
            Some("{A}")
        );
        assert_eq!(sel("/Event/Nope"), None);
        assert!(XPath::parse("relative/path").is_none());
    }

    #[test]
    fn refine_lookup_and_custom_maps() {
        let yaml = r#"
Description: Test
EventId: 1
Channel: Test
Provider: P
Maps:
  -
    Property: PayloadData1
    PropertyValue: "Bus: %BusType% / %Path%"
    Values:
      -
        Name: BusType
        Value: "/Event/EventData/Data[@Name=\"BusType\"]"
      -
        Name: Path
        Value: "/Event/EventData/Data[@Name=\"Cmd\"]"
        Refine: "[a-z]:\\\\[^ ]+\\.exe"
  -
    Property: NoSuchColumn
    PropertyValue: "x"
    Values: []
Lookups:
  -
    Name: BusType
    Default: Unknown code
    Values:
      7: USB
      0x0B: SATA
"#;
        let mut s = MapSet::default();
        assert!(s.load_str(yaml).is_empty());
        let xml = |bus: &str| {
            format!(
                r#"<Event><System><EventID>1</EventID><Channel>Test</Channel><Provider Name="P"/></System>
                <EventData><Data Name="BusType">{bus}</Data><Data Name="Cmd">run C:\Tools\x.exe now</Data></EventData></Event>"#
            )
        };
        let m = s.apply(&from_xml(xml("7"), 0, 0).unwrap()).unwrap();
        assert_eq!(m.payload[0].as_deref(), Some("Bus: USB / C:\\Tools\\x.exe"));
        let m = s.apply(&from_xml(xml("11"), 0, 0).unwrap()).unwrap();
        assert!(m.payload[0].as_deref().unwrap().starts_with("Bus: SATA"));
        let m = s.apply(&from_xml(xml("99"), 0, 0).unwrap()).unwrap();
        assert!(
            m.payload[0]
                .as_deref()
                .unwrap()
                .starts_with("Bus: Unknown code (99)")
        );
        assert_eq!(s.load_str(":::not yaml").len(), 1);
    }

    #[test]
    fn legacy_evt_logon_map() {
        let rec = EventRecord {
            format: LogFormat::Evt,
            channel: "Security".into(),
            provider: "Security".into(),
            event_id: 528,
            record_id: 1,
            time: 0,
            computer: "PC".into(),
            user_sid: None,
            data: [
                "Mr. Evil",
                "N-1A9ODN6ZXK4LQ",
                "(0x0,0x2A8E6)",
                "2",
                "User32  ",
                "Negotiate",
                "N-1A9ODN6ZXK4LQ",
                "-",
                "N-1A9ODN6ZXK4LQ$",
                "WORKGROUP",
                "(0x0,0x3E7)",
                "432",
                "-",
                "127.0.0.1",
                "0",
            ]
            .iter()
            .enumerate()
            .map(|(i, v)| ((i + 1).to_string(), (*v).to_owned()))
            .collect(),
            xml: None,
        };
        let m = MapSet::builtin().apply(&rec).unwrap();
        assert_eq!(m.description, "Successful logon");
        assert_eq!(m.user_name.as_deref(), Some("N-1A9ODN6ZXK4LQ\\Mr. Evil"));
        assert!(
            m.payload[0].as_deref().unwrap().contains("Interactive"),
            "{:?}",
            m.payload[0]
        );
    }
}
